-- Complemento de contagem: 6 médias do Evangelho, 2 difíceis, 6 expert.
WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($questions$[{"book":"evangelho","statement":"Qual é a orientação do capítulo XXII sobre a indissolubilidade do casamento?","option_a":"Tratar o vínculo como compromisso sério, respeitando os deveres e a dignidade das pessoas envolvidas.","option_b":"Considerar o casamento apenas um contrato econômico.","option_c":"Ignorar as consequências morais das separações.","option_d":"Impedir qualquer reflexão sobre situações de violência.","option_e":"Reduzir o vínculo à aprovação social.","correct_option":"A","explanation":"O capítulo examina o compromisso conjugal à luz dos ensinamentos de Jesus e dos deveres morais, sem transformar o tema em mera formalidade.","reference":"O Evangelho Segundo o Espiritismo, cap. XXII, itens 1–5.","difficulty":"medio","active":true},{"book":"evangelho","statement":"No capítulo XXIII, por que algumas máximas de Jesus parecem estranhas quando lidas literalmente?","option_a":"Porque devem ser descartadas como erros.","option_b":"Porque o sentido moral exige considerar o contexto e a linguagem figurada, em vez de uma leitura superficial.","option_c":"Porque foram acrescentadas por tradutores modernos.","option_d":"Porque tratam apenas de regras políticas.","option_e":"Porque não possuem aplicação prática.","correct_option":"B","explanation":"O capítulo explica passagens de linguagem forte ou figurada, buscando seu sentido moral e espiritual.","reference":"O Evangelho Segundo o Espiritismo, cap. XXIII, itens 1–4.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Qual é o sentido da imagem da candeia no capítulo XXIV?","option_a":"O conhecimento deve ser guardado para poucos.","option_b":"A verdade deve ser usada para obter prestígio.","option_c":"A luz do ensinamento deve ser colocada a serviço do esclarecimento e do bem.","option_d":"A vida espiritual deve permanecer oculta.","option_e":"A instrução moral é dispensável.","correct_option":"C","explanation":"A imagem da candeia simboliza a divulgação e a aplicação do ensinamento, que não deve ser escondido por egoísmo ou temor.","reference":"O Evangelho Segundo o Espiritismo, cap. XXIV, itens 1–4.","difficulty":"medio","active":true},{"book":"evangelho","statement":"O que o capítulo XXVIII reúne ao final da obra?","option_a":"Uma cronologia das viagens de Jesus.","option_b":"Uma lista de leis civis.","option_c":"Uma descrição dos mundos habitados.","option_d":"Preces espíritas e orientações relacionadas à oração em diferentes circunstâncias.","option_e":"Um catálogo de fenômenos naturais.","correct_option":"D","explanation":"O capítulo final reúne preces e instruções para diferentes situações, organizadas como coletânea de preces espíritas.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVIII.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Qual é a relação entre o capítulo XXIV e a responsabilidade de quem recebeu esclarecimento moral?","option_a":"O conhecimento recebido deve ser colocado em prática e compartilhado pelo exemplo, não ocultado por comodismo.","option_b":"O conhecimento deve ser usado para dominar os outros.","option_c":"A instrução só tem valor quando produz reconhecimento.","option_d":"Quem conhece a verdade fica dispensado de agir.","option_e":"A responsabilidade pertence somente a quem ensina.","correct_option":"A","explanation":"A candeia sob o alqueire representa o esclarecimento que não cumpre sua finalidade quando é escondido; o exemplo também comunica.","reference":"O Evangelho Segundo o Espiritismo, cap. XXIV, itens 1–4.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Como a coletânea do capítulo XXVIII se integra ao propósito geral da obra?","option_a":"Como substituição dos ensinamentos morais por fórmulas fixas.","option_b":"Como complemento prático que reúne exemplos de prece, mantendo a importância da sinceridade e do sentimento.","option_c":"Como prova de que a oração dispensa a reforma íntima.","option_d":"Como ritual obrigatório para todos os grupos.","option_e":"Como lista de pedidos materiais garantidos.","correct_option":"B","explanation":"A coletânea oferece exemplos de oração, mas o conjunto da obra valoriza intenção, sentimento e transformação moral.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVIII.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é a orientação da questão 919 para o conhecimento de si mesmo?","option_a":"Atribuir os próprios erros às circunstâncias.","option_b":"Avaliar-se somente pela opinião dos outros.","option_c":"Examinar diariamente a própria consciência, identificando o que pode ser corrigido.","option_d":"Comparar-se continuamente com pessoas consideradas inferiores.","option_e":"Considerar suficiente conhecer teorias morais.","correct_option":"C","explanation":"A questão 919 destaca o autoconhecimento e o exame diário da consciência como caminho importante para o aperfeiçoamento moral.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. XII, questão 919.","difficulty":"dificil","active":true},{"book":"evangelho","statement":"Como o capítulo XXVIII diferencia a oração sincera de uma fórmula meramente repetida?","option_a":"Pela extensão do texto recitado.","option_b":"Pelo número de pessoas presentes.","option_c":"Pelo uso de palavras antigas.","option_d":"Pela intenção, pelo sentimento e pela compreensão do que se expressa.","option_e":"Pela promessa de recompensa material.","correct_option":"D","explanation":"A coletânea deve ser compreendida à luz do princípio geral da obra: a prece vale pelo sentimento e pela intenção, não pela repetição vazia.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVII e cap. XXVIII.","difficulty":"dificil","active":true},{"book":"livro_espiritos","statement":"Qual é a consequência prática da questão 621 ao afirmar que a lei de Deus está escrita na consciência?","option_a":"O exame moral pode recorrer à consciência, mas exige esforço para reconhecer e aplicar corretamente essa lei.","option_b":"Toda decisão individual é automaticamente correta.","option_c":"As leis humanas tornam-se desnecessárias em qualquer sociedade.","option_d":"A consciência elimina a necessidade de educação.","option_e":"A moral depende exclusivamente de costumes externos.","correct_option":"A","explanation":"A questão 621 relaciona a lei divina à consciência; o desenvolvimento moral exige aprender a escutá-la e agir de acordo com ela.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. I, questão 621.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Por que a questão 919 considera o autoconhecimento um método de progresso moral?","option_a":"Porque elimina a necessidade de reparar erros.","option_b":"Porque permite identificar tendências, avaliar as próprias ações e orientar esforços concretos de transformação.","option_c":"Porque substitui a convivência social.","option_d":"Porque torna o indivíduo infalível.","option_e":"Porque transfere a responsabilidade ao guia espiritual.","correct_option":"B","explanation":"O exame de consciência torna possível reconhecer imperfeições e estabelecer ações concretas para corrigi-las.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. XII, questão 919.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a implicação doutrinária de reunir ensinamentos morais por tema, em vez de seguir apenas a cronologia dos Evangelhos?","option_a":"A cronologia é considerada falsa.","option_b":"A organização temática permite compreender relações entre máximas e deduzir aplicações morais, sem pretender reescrever os acontecimentos.","option_c":"A ordem temática elimina o contexto original.","option_d":"As passagens deixam de ter referência textual.","option_e":"A interpretação passa a depender de opiniões individuais.","correct_option":"B","explanation":"A introdução explica que os ensinamentos foram agrupados por natureza para facilitar a compreensão e a aplicação, preservando referências para consulta.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção I.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Como o controle universal evita que uma comunicação isolada se torne fundamento doutrinário?","option_a":"Exigindo que toda mensagem seja idêntica palavra por palavra.","option_b":"Privilegiando comunicações de um único centro.","option_c":"Submetendo princípios à concordância espontânea e independente em diferentes lugares, além do exame racional.","option_d":"Aceitando apenas mensagens que confirmem expectativas pessoais.","option_e":"Substituindo a razão pela quantidade de relatos.","correct_option":"C","explanation":"O controle universal não depende de identidade literal nem de uma fonte central: considera a concordância independente dos princípios e o exame da razão.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção II.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a consequência ética da máxima “fora da caridade não há salvação” para a relação entre crença e conduta?","option_a":"A crença declarada basta, mesmo sem mudança de comportamento.","option_b":"A caridade é um rito reservado a grupos específicos.","option_c":"A conduta não interfere na vida moral.","option_d":"A vivência do bem é critério central, de modo que a adesão verbal sem prática não realiza o princípio moral.","option_e":"A caridade se limita a contribuições financeiras.","correct_option":"D","explanation":"O capítulo XV coloca a caridade vivida no centro da orientação moral, acima de sinais exteriores ou declarações formais.","reference":"O Evangelho Segundo o Espiritismo, cap. XV, itens 1–5.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Por que a fé raciocinada é compatível com o progresso do conhecimento?","option_a":"Porque sua compreensão pode ser aprofundada e confrontada com a razão, sem depender de crença cega ou temor de investigação.","option_b":"Porque toda explicação racional deve ser rejeitada.","option_c":"Porque a fé só é válida quando não pode ser examinada.","option_d":"Porque o conhecimento científico determina sozinho a moral.","option_e":"Porque a fé elimina a necessidade de coerência.","correct_option":"A","explanation":"O capítulo XIX apresenta a fé que pode encarar a razão em qualquer época como mais sólida que a crença sem exame.","reference":"O Evangelho Segundo o Espiritismo, cap. XIX, itens 6–7.","difficulty":"expert","active":true}]$questions$::jsonb)
  AS x(book text, statement text, option_a text, option_b text, option_c text, option_d text, option_e text, correct_option text, explanation text, reference text, difficulty text, active boolean)
)
INSERT INTO public.questions (book, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, reference, difficulty, active)
SELECT book, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, reference, difficulty, active FROM incoming
ON CONFLICT (statement) DO NOTHING;
